#[test]
fn test_a_label_with_styled_words_has_no_text_of_its_own_and_still_holds_a_field() {
    // The W-9's `1 Name of entity` is a bold `1` and the words after it: the paragraph has no text run, its words are its inline children's. It is a label all the same (its
    // words are the children's), the field under it comes after the last of them, and the children are kept.
    let nodes: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let attrs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let regions: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let text: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pages: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ledger: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let layout: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let an: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let txt: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let out: &mut String = &mut crate::port::new_text();
    model_init(nodes, attrs, regions, text, pages, ledger, layout);
    let p: i32 = node_new(nodes, nk_paragraph(), 0);
    let sp: i32 = node_new(nodes, nk_span(), p);
    let t1: i32 = node_new(nodes, nk_text(), sp);
    let t2: i32 = node_new(nodes, nk_text(), p);
    let s1: i32 = text_len(text);
    node_set_sub(nodes, sp, 1);
    text_append_utf8(text, &crate::testport::text_blob("1")[..], 0, 1);
    node_set_text(nodes, t1, s1, 1);
    text_append_utf8(text, &crate::testport::text_blob(" Name of entity")[..], 0, 15);
    node_set_text(nodes, t2, s1 + 1, 15);
    node_add_region(nodes, regions, p, 1, 6200, 9700, 27400, 11400);
    fdt_field(an, txt, 4, -1, &crate::testport::text_blob("f1_01[0]")[..], &crate::testport::text_blob("")[..], &crate::testport::text_blob("")[..], 5860, 11800, 57600, 13200);
    fdt_html(0, nodes, attrs, regions, text, an, txt, out);
    crate::testport::assert_text(out, "<!doctype html><html><head><meta charset=\"utf-8\"><title></title></head><body><main><p><b>1</b> Name of entity<span data-emon=\"field\" data-emon-name=\"f1_01[0]\" data-emon-type=\"text\"></span></p></main></body></html>", "after the last inline");
}
